# Compos d'équipes (éducs) : onglets Plateaux et Entraîn., fiche terrain, présents, proposition, tableau, publication,
# contre-proposition, réponse de l'auteur, fiche joueur. Site de démo (sh tests/mkdemo.sh), puis :
# python3 tests/e2e_compos.py 390 844   (téléphone)   ·   python3 tests/e2e_compos.py 1180 820   (iPad paysage)
import sys, os, re
from playwright.sync_api import sync_playwright
BASE = 'http://localhost:8899/index.html'
OUT = os.environ.get('OUT', '/tmp/compos-shots/')
os.makedirs(OUT, exist_ok=True)
W, H = (int(sys.argv[1]), int(sys.argv[2])) if len(sys.argv) > 2 else (390, 844)
tag = '%dx%d' % (W, H)
res = []; errs = []
def check(n, c, i=''): res.append((n, c)); print(('OK  ' if c else 'BAD ') + n, '' if c else i)
def shot(pg, name, full=False): pg.screenshot(path=OUT + tag + '-' + name + '.png', full_page=full)
def noscroll(pg): return pg.evaluate('document.scrollingElement.scrollWidth <= document.documentElement.clientWidth + 1')   # (v54) pas innerWidth : en mobile, il grandit avec la page
def ev(pg, js): return pg.evaluate(js)
def nbp(pg): return pg.evaluate("(function(){var a=document.querySelectorAll('#nav a')[1];var n=a&&a.querySelector('.nb');return n?n.textContent:''})()")
with sync_playwright() as p:
    b = p.chromium.launch(); ctx = b.new_context(viewport={'width': W, 'height': H}, is_mobile=W < 700, has_touch=True); pg = ctx.new_page()
    pg.on('pageerror', lambda e: errs.append(str(e)))
    pg.goto(BASE); pg.evaluate('localStorage.clear()'); pg.reload(); pg.wait_for_timeout(600)
    pg.goto(BASE + '#/adultes'); pg.wait_for_timeout(400)
    pg.click('[data-act="adultWho"][data-w="e"]'); pg.wait_for_timeout(300)
    pg.click('[data-act="adultPick"][data-nom="Coach Nico"]'); pg.wait_for_timeout(300)
    for c in '2468': pg.click('#adultzone [data-k="%s"]' % c); pg.wait_for_timeout(40)
    pg.wait_for_timeout(1300)
    if '#/educ/bienvenue' in pg.url:
        for i in range(2): pg.click('[data-act="obNext"]'); pg.wait_for_timeout(300)
        pg.click('[data-act="obPick"] >> nth=0'); pg.wait_for_timeout(200)
        pg.click('[data-act="obEducDone"]'); pg.wait_for_timeout(1000)
    if pg.query_selector('.modal.sheet-news'):
        check('nouveauté des compos annoncée', 'compos' in pg.inner_text('.modal.sheet-news').lower())
        pg.click('.modal.sheet-news button[data-i="0"]'); pg.wait_for_timeout(300)
    pg.wait_for_timeout(600)
    check('4 onglets éduc', len(pg.query_selector_all('#nav a')) == 4)
    check('pastille sur Plateaux : 1 contre-proposition + 1 vote', nbp(pg) == '2', nbp(pg))
    # ----- onglet Plateaux -----
    pg.click('#nav a >> nth=1'); pg.wait_for_timeout(900)
    t = pg.inner_text('main')
    check('Plateaux : à venir et joués', 'À VENIR' in t.upper() and 'JOUÉS' in t.upper() and 'Plateau 3 - Muret' in t)
    check('Plateaux : la contre-proposition et le vote en tête', pg.query_selector('a.calert-top[href^="#/educ/avis/"]') is not None and pg.query_selector('a.calert-top.vote') is not None)
    check('pas de défilement horizontal (plateaux)', noscroll(pg))
    shot(pg, 'k01-compos', True)
    # ----- fiche terrain du groupe -----
    pg.click('#nav a >> nth=3'); pg.wait_for_timeout(900)   # (v43) l'onglet Enfants = directement la fiche terrain
    check('fiche terrain : 28 joueurs', re.sub(r'\s+', ' ', pg.inner_text('[data-act="tFiltre"][data-v="all"]')).upper() == 'TOUS 28', pg.inner_text('.tfil'))   # (v35) le nombre sous le nom
    pg.click('[data-act="tFiltre"][data-v="none"]'); pg.wait_for_timeout(300)
    check('filtre sans niveau : 3', len(pg.query_selector_all('#tlist .tfrow')) == 3)
    cid = ev(pg, "MC.app.S.cache.group.joueurs.find(p=>p.joueur.prenom==='Côme').joueur.id")
    check('pas de défilement horizontal (fiche terrain)', noscroll(pg))
    shot(pg, 'k02-terrain')
    # (v46) la liste ne se règle plus : le niveau et la passerelle de Côme se règlent sur sa fiche (toute la ligne y mène)
    pg.click('#tlist a.tfrow[href="#/educ/joueur/%s"]' % cid); pg.wait_for_timeout(1100)
    pg.click('[data-act="tkNiv"][data-v="B"]'); pg.wait_for_timeout(300)
    pg.click('[data-act="tkPas"][data-v="C"]'); pg.wait_for_timeout(300)
    check('(v43) pas de barre Enregistrer : enregistré au toucher', pg.query_selector('[data-act="tSave"], [data-act="tkSave"]') is None)
    pg.wait_for_timeout(1200)
    pg.go_back(); pg.wait_for_timeout(1000)
    check('(v46) de retour sur la liste : Côme n\'est plus « Sans niveau »', pg.query_selector('#tlist a.tfrow[href="#/educ/joueur/%s"]' % cid) is None and len(pg.query_selector_all('#tlist .tfrow')) == 2, len(pg.query_selector_all('#tlist .tfrow')))
    t = ev(pg, "MC.api.call('group',{token:MC.app.S.adult.token}).then(g=>JSON.stringify(g.joueurs.find(p=>p.joueur.prenom==='Côme').terrain))")
    check('fiche terrain enregistrée au serveur (B, passerelle C)', '"niveau":"B"' in t and '"passerelle":"C"' in t, t)
    # ----- un événement : les présents -----
    pg.goto(BASE + '#/educ/evt/sp-demo-p3/presents'); pg.wait_for_timeout(800)
    n0 = len(pg.query_selector_all('.cpres.on'))
    mid = ev(pg, "MC.app.S.cache.group.joueurs.find(p=>p.joueur.prenom==='Maël').joueur.id")
    pg.click('main details > summary'); pg.wait_for_timeout(200)   # les absents sont repliés
    pg.click('[data-act="prToggle"][data-id="%s"]' % mid); pg.wait_for_timeout(300)
    check('Maël coché présent (ajouté à la main)', len(pg.query_selector_all('.cpres.on')) == n0 + 1 and 'ajouté' in pg.inner_text('[data-act="prToggle"][data-id="%s"]' % mid))
    shot(pg, 'k03-evt')
    pg.click('[data-act="prSave"]'); pg.wait_for_timeout(700)
    check('présents enregistrés (ajouts)', ev(pg, "MC.app.S.cache.compos.evenements.find(e=>e.id==='sp-demo-p3').ajouts.length") == 1)
    check('pas de défilement horizontal (événement)', noscroll(pg))
    # ----- la page du plateau : présents, conseil, préparer la compo -----
    pg.click('a.btn2[href="#/educ/evt/sp-demo-p3"]'); pg.wait_for_timeout(700)
    check('page du plateau : carte des présents et conseil d\'équipes', pg.query_selector('.cpres-card') is not None and 'Conseillé' in pg.inner_text('main'))
    check('page du plateau : onglet Plateaux actif', 'PLATEAUX' in pg.inner_text('#nav a.on').upper())
    shot(pg, 'k03b-plateau', True)
    pg.click('a[href="#/educ/compo/sp-demo-p3"]'); pg.wait_for_timeout(700)
    check('réglages : format et équipes', pg.query_selector('[data-act="cFmt"]') is not None and len(pg.query_selector_all('.cstep:not(.cmont)')) == 3)
    # (v57) en décembre, le plateau part au jeu à 10 (une équipe A, une équipe B) : ce parcours essaie le jeu à 5 (3 niveaux)
    check('(v57) plateau de décembre : jeu à 10 par défaut, une équipe A et une B', ev(pg, "document.querySelector('[data-act=cFmt][data-v=\"10\"]').classList.contains('on') && [...document.querySelectorAll('.cstep .cnbv')].map(o => o.textContent).join(',') === '1,1,0'"))
    pg.click('[data-act="cFmt"][data-v="5"]'); pg.wait_for_timeout(400)
    check('(v57) jeu à 5 : le nombre d\'équipes conseillé pour ce format (A, B et C)', ev(pg, "[...document.querySelectorAll('.cstep .cnbv')].map(o => o.textContent).join(',')") == '1,1,1')
    shot(pg, 'k04-reglages', True)
    # (v49) les joueurs par équipe : équilibrés par défaut, réglables ; le total doit faire le nombre de présents
    def tl(): return ev(pg, "[...document.querySelectorAll('.ctail')].map(x=>x.querySelector('b').textContent+':'+x.querySelector('output').textContent)")
    t0 = tl(); vals = [int(x.split(':')[1]) for x in t0]
    npr = ev(pg, "MC.compos.presents(MC.app.S.cache.compos.evenements.find(e=>e.id==='sp-demo-p3')).length")
    check('(v49) joueurs par équipe : équilibrés, le total = les présents', vals and sum(vals) == npr and max(vals) - min(vals) <= 1, (t0, npr))
    check('(v49) replié, avec le résumé des tailles', not ev(pg, "document.querySelector('.ctaild').open") and all(x.split(':')[0] in pg.inner_text('.ctaild summary') for x in t0), pg.inner_text('.ctaild summary'))
    pg.click('.ctaild summary'); pg.wait_for_timeout(200)
    pg.click('.ctail >> nth=0 >> [data-act="cTail"][data-d="1"]'); pg.wait_for_timeout(200)
    check('(v49) une place de trop : dit, et « Proposer » attend', 'de trop' in pg.inner_text('.ctailp') and pg.is_disabled('[data-act="cPropose"]'), pg.inner_text('.ctailp'))
    pg.click('.ctail >> nth=1 >> [data-act="cTail"][data-d="-1"]'); pg.wait_for_timeout(200)
    check('(v49) le total retombe juste : « Proposer » revient, « Équilibrer » proposé', not pg.is_disabled('[data-act="cPropose"]') and pg.query_selector('[data-act="cTailEq"]') is not None)
    pg.click('[data-act="cTailEq"]'); pg.wait_for_timeout(200)
    check('(v49) « Équilibrer » : les tailles par défaut', tl() == t0, (tl(), t0))
    # (v48) le style « A forte » : une équipe A, les autres « B » (les C comptent comme des B)
    # (v50) les options (liste validée par Nicolas) à la place des styles
    ks = ev(pg, "[...new Set([...document.querySelectorAll('[data-act=\"cOpt\"]')].map(b=>b.getAttribute('data-k')))].join(',')")
    check('(v56) les options : organisation, joueurs par équipe, passerelles, copains', ks == 'orga,effectifs,passerelles,copains', ks)
    check('(v56) plus de compteur « Montent en A » ; Passerelles : Plaquage d\'abord ou Roulant, Roulant par défaut', pg.query_selector('.cmont') is None and pg.query_selector('[data-act="cOpt"][data-k="passerelles"][data-v="roulant"].on') is not None and pg.query_selector('[data-act="cOpt"][data-k="passerelles"][data-v="niveau"]') is not None)
    pg.click('[data-act="cOpt"][data-k="orga"][data-v="aforte"]'); pg.wait_for_timeout(200)
    check('(v48) A forte : la note des équipes', 'les équipes C comptent comme des B' in pg.inner_text('main'))
    pg.click('[data-act="cPropose"]'); pg.wait_for_timeout(900)
    af = ev(pg, """(()=>{const k=Object.keys(localStorage).find(k=>k.indexOf('mc-cdraft:')===0&&k.indexOf('sp-demo-p3')>0); const d=JSON.parse(localStorage.getItem(k)).vs[0]; const F=MC.compos.fiches(MC.app.S.cache.group);
      const a=d.equipes[0], As=d.equipes.flatMap(t=>t.joueurs).filter(j=>(F[j.id]||{}).niveau==='A');
      return JSON.stringify({ids:d.equipes.map(t=>t.id), style:d.reglages.style, tousA: As.length<=a.joueurs.length ? As.every(j=>a.joueurs.some(x=>x.id===j.id)) : a.joueurs.every(j=>(F[j.id]||{}).niveau==='A'),
        bC: d.equipes.slice(1).map(t=>t.joueurs.filter(j=>(F[j.id]||{}).niveau==='C').length)});})()""")
    check('(v48) A forte : A1 puis des équipes B, pas de C', '"ids":["A1","B' in af and '"C' not in af.split('"ids":')[1].split(']')[0] and '"style":"aforte"' in af, af)
    check('(v48) A forte : les Confirmés dans l\'équipe A', '"tousA":true' in af, af)
    bc = [int(x) for x in af.split('"bC":[')[1].split(']')[0].split(',') if x]
    check('(v48) A forte : les Débutants répartis dans les équipes B', len(bc) < 2 or max(bc) - min(bc) <= 1, bc)
    shot(pg, 'k04b-aforte', True)
    pg.click('[data-act="cDiscard"]'); pg.wait_for_timeout(300); pg.click('.modal button[data-i="0"]'); pg.wait_for_timeout(700)
    # (relecture v50) « Effacer le brouillon » garde les options
    check('(v50) brouillon effacé : les options restent (A forte)', pg.query_selector('[data-act="cOpt"][data-k="orga"][data-v="aforte"].on') is not None)
    pg.click('[data-act="cOpt"][data-k="orga"][data-v="niveau"]'); pg.wait_for_timeout(200)
    pg.click('[data-act="cPropose"]'); pg.wait_for_timeout(800)
    nteams = len(pg.query_selector_all('.ccol')); nchips = len(pg.query_selector_all('.ccol .cpj'))
    npres = ev(pg, "MC.compos.presents(MC.app.S.cache.compos.evenements.find(e=>e.id==='sp-demo-p3')).length")
    check('proposition : 3 équipes', nteams == 3, nteams)
    sz = ev(pg, "[...document.querySelectorAll('.clevel:not(.banc) .ccol')].map(c=>c.querySelectorAll('.cpj').length)")
    check('(v49) proposition : effectifs équilibrés', max(sz) - min(sz) <= 1, sz)
    # (v50) en haut de la compo : les options choisies, modifiables, puis « Générer une nouvelle compo » ; plus de barre d'actions en bas
    check('(v50) en haut : le résumé des options', pg.query_selector('details.cbopt') is not None and 'Jeu à' in pg.inner_text('.cbopt summary'), pg.inner_text('.cbopt summary') if pg.query_selector('.cbopt') else '')
    check('(v50) « Publier » en haut, plus de barre d\'actions en bas', pg.query_selector('.ctop [data-act="cPublish"]') is not None and pg.query_selector('.cdock [data-act="cPublish"]') is None and pg.query_selector('.cdock') is None)
    # (v54) plus de barre orange : le plaquage sous le repère de l'équipe se voit sur le bouclier ; la lettre et la flèche restent
    check('(v54) plus de barre orange sur les joueurs', pg.query_selector('.cpj.warn') is None and ev(pg, "[...document.querySelectorAll('.cpj')].every(e => getComputedStyle(e).borderLeftWidth === '1px')"))
    sa = ev(pg, "[...document.querySelectorAll('section[aria-label=\"Équipe A1\"] .pshield.mini')].map(e => [+e.textContent, e.classList.contains('sous')])")
    check('(v54) équipe A : bouclier rouge rosé pour moins de 3, et seulement pour eux', len(sa) > 0 and any(x[1] for x in sa) and all((x[0] < 3) == x[1] for x in sa), sa)
    check('(v54) le bouclier rouge rosé se distingue du rose', ev(pg, "(() => { const s = document.querySelector('.ccol .pshield.sous .ps-a'), n = document.querySelector('.ccol .pshield.mini:not(.sous) .ps-a'); return !!s && !!n && getComputedStyle(s).fill !== getComputedStyle(n).fill })()"))
    check('(v54) sous le repère : dit aussi à la lecture d\'écran', ev(pg, "document.querySelector('.ccol .pshield.sous').getAttribute('aria-label').indexOf('sous le repère') > 0"))
    check('(v54) la légende dit ce que veut dire le bouclier rouge rosé', 'sous le repère' in pg.inner_text('.clegend') and pg.query_selector('.clegend .pshield.sous') is not None)
    check('(v54) la lettre et la flèche restent pour un joueur hors de son niveau', pg.query_selector('.ccol .cfl.cpas') is not None and re.match(r'^[↑↓][ABC]$', pg.inner_text('.ccol .cfl.cpas')) is not None, pg.inner_text('.ccol .cfl.cpas') if pg.query_selector('.ccol .cfl.cpas') else '')
    # (v54, O1) la section Options : le même cadre, moins d'écart entre plié et déplié, un « ? » par ligne
    hp = ev(pg, "document.querySelector('.cbopt').getBoundingClientRect().height")
    yh = ev(pg, "document.querySelector('.cbopt > summary .ott').getBoundingClientRect().top")
    pg.click('.cbopt > summary .ott'); pg.wait_for_timeout(250)
    hd = ev(pg, "document.querySelector('.cbopt').getBoundingClientRect().height")
    check('(v54) déplié : beaucoup moins haut qu\'avant (1410 px au téléphone)', hd < 760, hd)
    check('(v54) l\'en-tête ne bouge pas en dépliant, et dit « Replier »', abs(ev(pg, "document.querySelector('.cbopt > summary .ott').getBoundingClientRect().top") - yh) < 1 and 'REPLIER' in pg.inner_text('.cbopt .oac').upper() and 'MODIFIER' not in pg.inner_text('.cbopt .oac').upper(), pg.inner_text('.cbopt .oac'))
    lignes = ev(pg, "[...document.querySelectorAll('.cbopt .oli')].map(e => !!e.querySelector('.aide-q'))")
    check('(v54) un « ? » au début de chaque ligne (v56 : 7 lignes, sans « Qui change de niveau »)', len(lignes) == 7 and all(lignes), lignes)
    check('(v54) le « ? » est bien au début de la ligne', ev(pg, "[...document.querySelectorAll('.cbopt .oli:not(.otail)')].every(l => { const q = l.querySelector('.aide-q').getBoundingClientRect(), r = l.getBoundingClientRect(); return q.left - r.left < 20 })"))
    check('(v54) rien ne déborde des lignes', ev(pg, "[...document.querySelectorAll('.cbopt .oli, .cbopt .oseg, .cbopt .opt')].every(e => e.scrollWidth <= e.clientWidth + 1)") and noscroll(pg))
    for k, txt in (('o-orga', 'A forte'), ('o-effectifs', 'Suivre les niveaux'), ('o-passerelles', 'à son tour'), ('o-copains', "Copains d'abord"), ('o-format', 'Jeu à 10'), ('o-equipes', 'niveau voisin'), ('o-tailles', 'Ajuster'), ('o-garder', 'Pas placés')):
        pg.evaluate("(k) => document.querySelector('.cbopt .aide-q[data-aide=\"' + k + '\"]').scrollIntoView({ block: 'center' })", k); pg.wait_for_timeout(120)   # défiler ferme la bulle : c'est voulu
        pg.click('.cbopt .aide-q[data-aide="%s"]' % k); pg.wait_for_timeout(120)
        check('(v54) « ? » %s : la règle s\'affiche' % k, pg.query_selector('.aide-bulle') is not None and txt in pg.inner_text('.aide-bulle'), pg.inner_text('.aide-bulle') if pg.query_selector('.aide-bulle') else '')
        pg.evaluate("document.querySelector('.aide-bulle') && document.querySelector('.aide-q.ouvert').dispatchEvent(new PointerEvent('pointerdown', { bubbles: true }))"); pg.wait_for_timeout(80)
        check('(v54) « ? » %s : un 2e toucher ferme la bulle' % k, pg.query_selector('.aide-bulle') is None)
    check('(v54) le « ? » de la ligne des joueurs ne la déplie pas', not ev(pg, "document.querySelector('.cbopt .ctaild').open"))
    # beaucoup d'équipes : le résumé des joueurs passe à la ligne, rien ne se chevauche ni ne sort de l'écran
    for i in range(4): pg.click('.cbopt [data-act="cNb"][data-n="B"][data-d="1"]'); pg.wait_for_timeout(120)
    ot = ev(pg, "(() => { const o = document.querySelector('.otail .olab').getBoundingClientRect(), c = document.querySelector('.otail .ctsum').getBoundingClientRect(), l = document.querySelector('.otail summary .lnk').getBoundingClientRect(), v = document.documentElement.clientWidth; return { n: document.querySelector('.otail .ctsum').textContent, chevauche: c.top < o.bottom - 1 && c.left < o.right - 1, sort: Math.max(c.right, l.right) > v, large: document.scrollingElement.scrollWidth > v + 1 } })()")
    check('(v54) 7 équipes : la ligne des joueurs ne se chevauche pas et reste dans l\'écran', not ot['chevauche'] and not ot['sort'] and not ot['large'] and 'B4' in ot['n'], ot)
    for i in range(4): pg.click('.cbopt [data-act="cNb"][data-n="B"][data-d="-1"]'); pg.wait_for_timeout(120)
    # le doigt qui part défiler depuis un « ? » : pas de bulle
    pg.evaluate("document.querySelector('.cbopt .aide-q[data-aide=\"o-orga\"]').scrollIntoView({ block: 'center' })"); pg.wait_for_timeout(120)
    pg.evaluate("(() => { const q = document.querySelector('.cbopt .aide-q[data-aide=\"o-orga\"]'); q.dispatchEvent(new PointerEvent('pointerdown', { bubbles: true })); document.dispatchEvent(new PointerEvent('pointercancel', { bubbles: true })); })()"); pg.wait_for_timeout(200)
    check('(v54) un défilement qui démarre sur un « ? » : pas de bulle', pg.query_selector('.aide-bulle') is None)
    # le doigt tenu : la bulle s'ouvre, et se ferme au lâcher
    pg.evaluate("document.querySelector('.cbopt .aide-q[data-aide=\"o-orga\"]').dispatchEvent(new PointerEvent('pointerdown', { bubbles: true }))"); pg.wait_for_timeout(500)
    tenu = pg.query_selector('.aide-bulle') is not None
    pg.evaluate("document.dispatchEvent(new PointerEvent('pointerup', { bubbles: true }))"); pg.wait_for_timeout(80)
    check('(v54) doigt tenu sur un « ? » : la bulle, fermée au lâcher', tenu and pg.query_selector('.aide-bulle') is None, tenu)
    if ev(pg, "document.querySelector('.cbopt').open"): pg.click('.cbopt > summary .ott'); pg.wait_for_timeout(250)
    check('(v54) replié : le résumé revient, l\'en-tête dit « Modifier »', 'Jeu à' in pg.inner_text('.cbopt summary') and 'MODIFIER' in pg.inner_text('.cbopt .oac').upper())
    avant = ev(pg, "[...document.querySelectorAll('.ccol .cpj')].map(x=>x.getAttribute('data-id')).join(',')")
    pg.click('.cbopt summary'); pg.wait_for_timeout(200)
    pg.click('.cbopt [data-act="cOpt"][data-k="copains"][data-v="dabord"]'); pg.wait_for_timeout(300)
    check('(v50) le panneau reste ouvert, « pas encore appliquées »', ev(pg, "document.querySelector('.cbopt').open") and pg.query_selector('.cbopt .cbdiff') is not None)
    pg.click('.cbopt [data-act="cRegen"]'); pg.wait_for_timeout(700)
    dr = ev(pg, "(()=>{const k=Object.keys(localStorage).find(k=>k.indexOf('mc-cdraft:')===0&&k.indexOf('sp-demo-p3')>0); return JSON.parse(localStorage.getItem(k)).vs[0].reglages.opts.copains;})()")
    check('(v50) « Générer une nouvelle compo » : avec les nouvelles options', dr == 'dabord' and pg.query_selector('.cbopt .cbdiff') is None, dr)
    pg.click('[data-act="cUndo"]'); pg.wait_for_timeout(500)
    check('(v50) « Annuler » fait revenir la compo d\'avant', ev(pg, "[...document.querySelectorAll('.ccol .cpj')].map(x=>x.getAttribute('data-id')).join(',')") == avant)
    # (relecture v50) « Garder mes placements » : seulement le format et les équipes ; les autres options attendent « Générer »
    check('(v50) rien à garder (seuls les copains changent) : « Garder mes placements » inactif', pg.query_selector('.cbopt .cbdiff') is not None and pg.is_disabled('.cbopt [data-act="cKeep"]'))
    if not ev(pg, "document.querySelector('.cbopt').open"): pg.click('.cbopt summary'); pg.wait_for_timeout(200)
