    check('(v57) matchs : repris du dernier entraînement, toujours deux équipes', eq == 'Équipe 1,Équipe 2', eq)
    pg.click('[data-act="cDiscard"]'); pg.wait_for_timeout(300); pg.click('.modal button[data-i="0"]'); pg.wait_for_timeout(700)
    pg.click('[data-act="cPropose"]'); pg.wait_for_timeout(1000)
    mh = ev(pg, "[...document.querySelectorAll('.clevel .clvh')].map(x=>x.textContent.split(' ·')[0]).join('|')")
    check('(v57) matchs : un seul match', mh.startswith('Match 1') and 'Match 2' not in mh, mh)
    check('matchs : « Équipe 1 contre Équipe 2 »', 'Équipe 1 contre Équipe 2' in pg.inner_text('.cboard2') and 'Équipe 3' not in pg.inner_text('.cboard2'))
    check('matchs : pas de défilement horizontal', noscroll(pg))
    shot(pg, 'k16-matchs'); shot(pg, 'k16-matchs-full', True)
    pg.click('[data-act="cPublish"]'); pg.wait_for_timeout(400)
    if pg.query_selector('.modal'): pg.click('.modal button[data-i="0"]'); pg.wait_for_timeout(1000)
    cm = ev(pg, "JSON.stringify(MC.app.S.cache.compos.compos.find(c=>c.evenementId==='sp-demo-e1'&&c.partie==='matchs'))")
    check('matchs publiés (équilibrés)', cm is not None and '"mode":"equilibre"' in cm and '"nom":"Équipe 1"' in cm and '"cote"' not in cm)
    pg.goto(BASE + '#/educ/evt/sp-demo-e1'); pg.wait_for_timeout(700)
    check('entraînement : ateliers et matchs faits', len(pg.query_selector_all('.cpart.ok')) == 2)
    pg.goto(BASE + '#/educ/entrainements'); pg.wait_for_timeout(700)
    # (visuels v2, UI-11) un entraînement à venir : deux actions « Ateliers · Prêt ✓ » et « Matchs · Prêt ✓ » sous la carte
    acts = pg.query_selector_all('li:has(a[href="#/educ/evt/sp-demo-e1"]) .cev-a')
    check('liste : ateliers ✓ matchs ✓', len(acts) == 2 and 'ATELIERS' in acts[0].inner_text().upper() and 'PRÊT ✓' in acts[0].inner_text().upper() and 'MATCHS' in acts[1].inner_text().upper() and 'PRÊT ✓' in acts[1].inner_text().upper(), [a.inner_text() for a in acts])
    # ----- jeu à 10 : postes -----
