    shot(pg, 'k11-choix-pilier')
    ids3 = ev(pg, "[...document.querySelectorAll('.modal .pprow')].filter(r => !r.closest('details:not([open])')).slice(0, 3).map(r => r.querySelector('.ppb').getAttribute('data-ppid'))")
    t0 = ev(pg, "document.querySelector('.modal .pprow .ppb').getAttribute('data-ppt')")
