    # jeu à 5 : « Ajouter des joueurs », la liste reste ouverte
    pg.evaluate("document.querySelector('.cbopt').open = true"); pg.wait_for_timeout(200)   # (v50) le panneau du haut
    pg.locator('.cbopt [data-act="cFmt"][data-v="5"]').evaluate('e=>e.click()'); pg.wait_for_timeout(300)
    pg.locator('.cbopt [data-act="cKeep"]').evaluate('e=>e.click()'); pg.wait_for_timeout(700)
    n1 = ev(pg, "document.querySelectorAll('.ccol')[1].querySelectorAll('.cpj').length")
    pg.locator('.ccol >> nth=1 >> .cslot').evaluate('e=>e.click()'); pg.wait_for_timeout(400)
